import{_ as t,o,c as a,a0 as r}from"./chunks/framework.L_oL6aia.js";const d=JSON.parse('{"title":"Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),s={name:"privacy.md"};function i(n,e,l,c,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Keelhaven is built so that there is nothing to have a policy about.</p><ul><li><strong>No account.</strong> There is nothing to sign up for and no identity attached to your use of the app.</li><li><strong>No telemetry.</strong> The app does not phone home — no analytics, no crash reporting, no usage statistics.</li><li><strong>No server of ours.</strong> Your backups travel directly from your Mac to the destination you configured — a local drive, your NAS, or your own S3-compatible bucket. Keelhaven operates no server that could see them.</li><li><strong>Encrypted before it leaves.</strong> Everything is encrypted on your Mac before a single byte is uploaded. The repository password stays in your macOS Keychain and is never sent anywhere.</li></ul><p>That covers the app, which is the part that touches your files. Two things around it are worth stating plainly:</p><ul><li><strong>This website</strong> is a static site served by GitHub Pages; GitHub sees the requests it serves, as any web host does. It uses Google Analytics for basic visit statistics — the only third party involved, and it applies to the website only, never the app.</li><li><strong>Support email</strong> sent to our address is routed through Cloudflare Email Routing to a mailbox we read. We see your address and whatever you write, and use it only to answer you.</li></ul><p>Questions? See the <a href="/#faq">FAQ</a> or email us — the address is in the site footer.</p>',6)])])}const y=t(s,[["render",i]]);export{d as __pageData,y as default};
